          telemetry.midEnergy = 0;
          telemetry.trebleEnergy = 0;
          telemetry.overallEnergy = 0;
          telemetry.rms = 0;
          telemetry.peak = 0;
          telemetry.rmsDb = -100;
          telemetry.peakDb = -100;
