    const padded = new Uint8Array(paddedLen);
    if (len > 0) padded.set(u8, 0);
    padded[len] = 0x80;
    const dv = new DataView(padded.buffer);
    const bitLen = len * 8;
    dv.setUint32(paddedLen - 8, Math.floor(bitLen / 0x100000000) >>> 0, false);
    dv.setUint32(paddedLen - 4, bitLen >>> 0, false);

    let h0 = 0x6a09e667;
    let h1 = 0xbb67ae85;
    let h2 = 0x3c6ef372;
    let h3 = 0xa54ff53a;
    let h4 = 0x510e527f;
    let h5 = 0x9b05688c;
    let h6 = 0x1f83d9ab;
    let h7 = 0x5be0cd19;

    const w = SHA256_W;
