            const peakQuiet = !hasPeak || t.peak < silencePeakThreshold;
            const energyQuiet = !hasEnergy || t.overallEnergy < silenceEnergyThreshold;
            const dbQuiet = !hasRmsDb || t.rmsDb <= silenceDbThreshold;
