            accessTokenPresent: entry.accessTokenPresent,
            expiresAt: entry.expiresAt,
            verifiedAt: entry.verifiedAt,
            accountHint: entry.accountHint,
            lastStatus: entry.lastStatus,
            refreshCapable: entry.refreshCapable
